<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DIC Admin — PHP/MySQL</title><link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;background:#f4f8f2;color:#224632;font-family:'Hind Siliguri',sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}.wrap{max-width:1150px;margin:auto;padding:25px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px}.top h1{margin:0}.card{background:white;border:1px solid #dce7d8;border-radius:14px;padding:22px;margin:15px 0}.layout{display:grid;grid-template-columns:230px 1fr;gap:20px}.menu{display:grid;gap:8px}.menu button{border:0;border-radius:9px;padding:10px;background:#eef5eb;text-align:left}.menu button.active,.primary{background:#2c7941;color:white}.primary,.secondary{border:0;border-radius:8px;padding:10px 18px}.secondary{background:#e8eee6}.form{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-weight:600}input,textarea{display:block;width:100%;padding:10px;border:1px solid #ccd9c7;border-radius:8px;margin-top:5px}textarea{min-height:90px}.full{grid-column:1/-1}.row{padding:12px 0;border-bottom:1px solid #e7eee3;display:flex;align-items:center;justify-content:space-between;gap:12px}.hidden{display:none!important}#status{background:#fff3d6;padding:12px;border-radius:9px;margin:16px 0}@media(max-width:750px){.layout,.form{grid-template-columns:1fr}.menu{display:flex;overflow:auto}.menu button{white-space:nowrap}.top{flex-wrap:wrap}}</style></head><body><div class="wrap"><header class="top"><div><h1>ডেমরা আইডিয়াল কলেজ</h1><div>Custom CMS · PHP + MySQL</div></div><div><a href="../index.html">← Website</a> <button id="logout" class="secondary hidden">Logout</button></div></header><div id="status" role="status">Checking backend…</div><section id="login" class="card hidden"><h2>Admin Login</h2><form id="loginForm"><label>Email<input id="email" type="email" autocomplete="username" required></label><label>Password<input id="password" type="password" autocomplete="current-password" required></label><p><button class="primary">Login</button></p></form></section><div id="dashboard" class="layout hidden"><aside class="card"><h3>Management</h3><div id="menu" class="menu"></div></aside><main><section class="card"><h2 id="heading">Content</h2><form id="form" class="form"><input id="id" type="hidden"><label>নাম / Title<input id="title" required maxlength="255"></label><label>Subject<input id="subject" maxlength="190"></label><label>Designation<input id="designation" maxlength="190"></label><label>Department<input id="department" maxlength="190"></label><label>Image URL<input id="image_url" type="url"></label><label>PDF / Attachment URL<input id="attachment_url" type="url"></label><label>Slug<input id="slug" maxlength="190"></label><label>Sort Order<input id="sort_order" type="number" value="0"></label><label class="full">Details<textarea id="body"></textarea></label><label><input type="checkbox" id="published" style="width:auto;display:inline"> Published</label><div class="full"><button class="primary">Save</button> <button type="button" id="new" class="secondary">New Entry</button></div></form></section><section class="card"><h2>Existing Content</h2><div id="items"></div></section></main></div></div><script>
const $=id=>document.getElementById(id),api='../api/index.php?action=',types={teacher:'শিক্ষকবৃন্দ',notice:'নোটিশ',slide:'স্লাইডশো',page:'পেজ',news:'সংবাদ',event:'অনুষ্ঠান',gallery:'গ্যালারি',admission:'ভর্তি',academic:'একাডেমিক'};let token='',type='teacher',records=[];
function show(id,yes){$(id).classList.toggle('hidden',!yes)}function status(s){$('status').textContent=s}
async function call(action,body){const opts={credentials:'same-origin',headers:{'Accept':'application/json'}};if(body!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';if(token)opts.headers['X-CSRF-Token']=token;opts.body=JSON.stringify(body)}const res=await fetch(api+encodeURIComponent(action),opts);let data;try{data=await res.json()}catch{throw Error('Server response was not JSON')}if(!res.ok)throw Error(data.error||'Request failed');return data}
function clear(){ $('form').reset();$('id').value='';$('sort_order').value=0}
function menu(){ $('menu').replaceChildren();Object.entries(types).forEach(([key,label])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.className=key===type?'active':'';b.onclick=()=>{type=key;clear();menu();load()};$('menu').append(b)})}
async function session(){try{const s=await call('session');if(!s.authenticated){show('login',true);show('dashboard',false);show('logout',false);status('Admin Login required');return}token=s.csrf;show('login',false);show('dashboard',true);show('logout',true);status('Logged in: '+s.user.email);menu();await load()}catch(e){status('Backend setup: '+e.message)}}
async function load(){try{const d=await call('list&type='+type);records=d.items;$('heading').textContent=types[type]+' Manager';$('items').replaceChildren();if(!records.length)$('items').textContent='No records yet';records.forEach(r=>{const div=document.createElement('div');div.className='row';const label=document.createElement('span');label.textContent=r.title+' — '+(Number(r.published)?'Published':'Draft');const actions=document.createElement('div');const edit=document.createElement('button');edit.className='secondary';edit.textContent='Edit';edit.onclick=()=>{for(const k of ['id','title','subject','designation','department','image_url','attachment_url','slug','sort_order','body'])$(k).value=r[k]??'';$('published').checked=!!Number(r.published);window.scrollTo({top:0,behavior:'smooth'})};const del=document.createElement('button');del.className='secondary';del.textContent='Delete';del.onclick=async()=>{if(!confirm('Delete this record?'))return;try{await call('delete',{id:r.id});await load()}catch(e){status(e.message)}};actions.append(edit,' ',del);div.append(label,actions);$('items').append(div)})}catch(e){status(e.message)}}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await call('login',{email:$('email').value,password:$('password').value});token=d.csrf;$('password').value='';await session()}catch(e){status(e.message)}};
$('form').onsubmit=async e=>{e.preventDefault();const data={type};for(const k of ['id','title','subject','designation','department','image_url','attachment_url','slug','sort_order','body'])data[k]=$(k).value;data.published=$('published').checked;try{await call('save',data);status('Saved');clear();await load()}catch(e){status(e.message)}};
$('new').onclick=clear;$('logout').onclick=async()=>{try{await call('logout',{});token='';await session()}catch(e){status(e.message)}};session();
</script></body></html>